[InitializeOnLoad]public static class CityGunShopBuild{static CityGunShopBuild(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityGunShop.request"))return;var mode=File.ReadAllText("CityGunShop.request").Trim();File.Delete("CityGunShop.request");try{if(mode=="build")Build();else if(mode=="polish")Polish();else Audit();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/GunShop.txt",e.ToString());Debug.LogException(e);}}static void Audit(){var sc=SceneManager.GetActiveScene();var ts=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.name=="Gun Shop").ToArray();var b=new StringBuilder("Scene="+sc.path+" target count="+ts.Length+"\n");foreach(var t in ts){b.AppendLine("TARGET "+t.name+" position="+t.position+" rotation="+t.eulerAngles+" scale="+t.lossyScale);foreach(var f in t.GetComponentsInChildren<MeshFilter>(true)){b.AppendLine("MESH="+f.name+" local="+f.sharedMesh.bounds+" path="+AssetDatabase.GetAssetPath(f.sharedMesh)+" triangles="+f.sharedMesh.triangles.Length/3+" transform="+f.transform.localPosition+" "+f.transform.localEulerAngles);var r=f.GetComponent<Renderer>();b.AppendLine("WORLD="+r.bounds+" MATERIALS="+string.Join("|",r.sharedMaterials.Select(m=>AssetDatabase.GetAssetPath(m))));}var source=t.GetComponent<MeshFilter>().sharedMesh;var vs=source.vertices;var ids=source.triangles;foreach(var axis in new[]{Vector3.forward,Vector3.back,Vector3.left,Vector3.right}){float edge=Vector3.Dot(source.bounds.center,axis)+Vector3.Dot(source.bounds.extents,new Vector3(Mathf.Abs(axis.x),0,Mathf.Abs(axis.z)));b.AppendLine("FACE="+axis+" edge="+edge);var heights=new System.Collections.Generic.SortedSet<float>();for(int i=0;i<ids.Length;i+=3){var a=vs[ids[i]];var c=vs[ids[i+1]];var d=vs[ids[i+2]];if(Vector3.Dot(Vector3.Cross(c-a,d-a).normalized,axis)>.8f&&new[]{a,c,d}.All(p=>Vector3.Dot(p,axis)>edge-2)){foreach(var p in new[]{a,c,d})heights.Add(Mathf.Round(p.y*1000)/1000);}}b.AppendLine("Wall heights="+string.Join(",",heights));}var cap=typeof(CityTaxiStandBuild).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);foreach(var axis in new[]{Vector3.forward,Vector3.back,Vector3.left,Vector3.right})cap.Invoke(null,new object[]{sc,t.TransformPoint(source.bounds.center+axis*36+Vector3.up*2),t.TransformPoint(source.bounds.center),"GunShop-Before-"+axis.x+"-"+axis.z});}File.WriteAllText("FinalEnvironmentRoadReview/GunShop.txt",b.ToString());}const string Atlas="Assets/Scenes/Oasis/CityHospital/City Hospital Facade Atlas.png",MaterialPath="Assets/Scenes/Oasis/CityHospital/City Hospital Mobile.mat",Dir="Assets/Scenes/Oasis/GunShop",Backup="FinalEnvironmentRoadBackup/BeforeGunShop";
static Mesh Front(Mesh original,out int keptUpper){var m=new Mesh();m.name="Weapon shop ground floor "+original.name;var vertices=original.vertices;var oldIds=original.triangles;var p=vertices.ToList();var n=original.normals.ToList();var tan=original.tangents.ToList();bool hasTangents=tan.Count==p.Count;var colors=original.colors32.ToList();bool hasColors=colors.Count==p.Count;var coords=new List<Vector4>[8];for(int i=0;i<8;i++){coords[i]=new List<Vector4>();original.GetUVs(i,coords[i]);}if(coords[0].Count!=p.Count)throw new Exception("Missing original UVs");var body=new List<int>();var shop=new List<int>();var b=original.bounds;keptUpper=0;
for(int k=0;k<oldIds.Length;k+=3){var tri=new[]{oldIds[k],oldIds[k+1],oldIds[k+2]};bool oldFront=tri.All(i=>vertices[i].z>b.max.z-2.9f&&vertices[i].y<=5.0801f);if(oldFront)continue;body.AddRange(tri);if(tri.Any(i=>vertices[i].y>5.0801f))keptUpper++;}
Action<float,float,float,float,Rect,bool> quad=(x0,x1,y0,y1,r,gun)=>{int start=p.Count;var points=new[]{new Vector3(b.max.x-x0,y0,b.max.z+.008f),new Vector3(b.max.x-x0,y1,b.max.z+.008f),new Vector3(b.max.x-x1,y1,b.max.z+.008f),new Vector3(b.max.x-x1,y0,b.max.z+.008f)};var uvs=new[]{new Vector2(r.xMin,r.yMin),new Vector2(r.xMin,r.yMax),new Vector2(r.xMax,r.yMax),new Vector2(r.xMax,r.yMin)};for(int i=0;i<4;i++){p.Add(points[i]);n.Add(Vector3.forward);if(hasTangents)tan.Add(new Vector4(-1,0,0,-1));if(hasColors)colors.Add(new Color32(255,255,255,255));coords[0].Add(new Vector4((gun?128:32)+uvs[i].x,uvs[i].y,0,0));for(int ch=1;ch<8;ch++)if(coords[ch].Count>0)coords[ch].Add(Vector4.zero);}shop.AddRange(new[]{start,start+1,start+2,start,start+2,start+3});};
float width=b.size.x,middle=8.8f,left=(width-middle)*.5f,right=left+middle;const float floor=1.09f,glass=4.0f,top=5.08f;
quad(left,right,floor,glass,new Rect(0,0,1,.68f),true);for(int side=0;side<2;side++){float start=side==0?0:right,end=side==0?left:width;int count=Mathf.CeilToInt((end-start)/3.5f);for(int j=0;j<count;j++){var region=(side+j)%2==0?new Rect(.015f,0,.32f,.68f):new Rect(.665f,0,.32f,.68f);quad(Mathf.Lerp(start,end,j/(float)count),Mathf.Lerp(start,end,(j+1f)/count),floor,glass,region,true);}}
quad(left,right,glass,top,new Rect(0,.69f,1,.31f),true);quad(0,left,glass,top,new Rect(.08f,.69f,.055f,.31f),true);quad(right,width,glass,top,new Rect(.08f,.69f,.055f,.31f),true);quad(0,width,0,floor,new Rect(.15f,.1f,.001f,.8f),false);
m.Clear();m.indexFormat=p.Count>65535?UnityEngine.Rendering.IndexFormat.UInt32:UnityEngine.Rendering.IndexFormat.UInt16;m.SetVertices(p);m.SetNormals(n);if(hasTangents)m.SetTangents(tan);if(hasColors)m.SetColors(colors);for(int ch=0;ch<8;ch++)if(coords[ch].Count>0)m.SetUVs(ch,coords[ch]);m.subMeshCount=2;m.SetTriangles(body,0);m.SetTriangles(shop,1);m.RecalculateBounds(); // Source vertices and all upper triangles/UVs/normals remain identical.
var nv=m.vertices;var nu=new List<Vector4>();m.GetUVs(0,nu);var ou=new List<Vector4>();original.GetUVs(0,ou);if(nv.Length<vertices.Length||nu.Count<vertices.Length||ou.Count<vertices.Length)throw new Exception("UV count mismatch: built="+nu.Count+" original="+ou.Count+" vertices="+vertices.Length);for(int i=0;i<vertices.Length;i++)if(nv[i]!=vertices[i]||nu[i]!=ou[i])throw new Exception("Original upper vertex/UV changed");return m;}
static void Build(){var sc=SceneManager.GetActiveScene();var t=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Single(x=>x.name=="Gun Shop");var filters=t.GetComponentsInChildren<MeshFilter>(true);if(filters.Any(f=>f.sharedMesh&&f.sharedMesh.name.StartsWith("Weapon shop ground floor")))throw new Exception("Already built; refusing duplicate placement");Directory.CreateDirectory(Backup);EditorSceneManager.SaveScene(sc,Backup+"/Scene.unity",true);var targetMatrix=t.localToWorldMatrix;var upperMaterial=t.GetComponent<Renderer>().sharedMaterial;var material=AssetDatabase.LoadAssetAtPath<Material>(MaterialPath);if(ShaderUtil.ShaderHasError(material.shader))throw new Exception("Shared shader errors");var atlas=new Texture2D(2,2,TextureFormat.RGB24,false);atlas.LoadImage(File.ReadAllBytes(Atlas));if(atlas.width!=4096||atlas.height!=2048)throw new Exception("Unexpected shared atlas size");var before=atlas.GetPixels32();var art=new Texture2D(2,2,TextureFormat.RGB24,false);art.LoadImage(File.ReadAllBytes("FinalEnvironmentRoadReview/GunShop-Facade-Source.png"));var r=new RectInt(16,16,1800,800);for(int y=-8;y<r.height+8;y++)for(int x=-8;x<r.width+8;x++)atlas.SetPixel(r.x+x,r.y+y,art.GetPixelBilinear(Mathf.Clamp01((x+.5f)/r.width),Mathf.Clamp01((y+.5f)/r.height)));atlas.Apply();var after=atlas.GetPixels32();int changedOutside=0;for(int y=0;y<2048;y++)for(int x=0;x<4096;x++)if((x<r.x-8||x>=r.xMax+8||y<r.y-8||y>=r.yMax+8)&&!before[y*4096+x].Equals(after[y*4096+x]))changedOutside++;if(changedOutside!=0)throw new Exception("Hospital/clothing atlas area changed");var guid=AssetDatabase.AssetPathToGUID(Atlas);File.WriteAllBytes(Atlas,atlas.EncodeToPNG());UnityEngine.Object.DestroyImmediate(atlas);UnityEngine.Object.DestroyImmediate(art);AssetDatabase.ImportAsset(Atlas,ImportAssetOptions.ForceSynchronousImport);material.SetVector("_CityWeaponAtlasRect",new Vector4(r.width/4096f,r.height/2048f,r.x/4096f,r.y/2048f));EditorUtility.SetDirty(material);Directory.CreateDirectory(Dir);AssetDatabase.Refresh();var report=new StringBuilder();int originalTriangles=0,finalTriangles=0;for(int i=0;i<filters.Length;i++){var f=filters[i];var original=f.sharedMesh;var built=Front(original,out int upper);originalTriangles+=original.triangles.Length/3;finalTriangles+=built.triangles.Length/3;built.name="Weapon Shop Ground Floor LOD"+i;AssetDatabase.CreateAsset(built,Dir+"/"+built.name+".asset");f.sharedMesh=built;f.GetComponent<Renderer>().sharedMaterials=new[]{upperMaterial,material};PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f.GetComponent<Renderer>());report.AppendLine("LOD"+i+" original="+original.triangles.Length/3+" final="+built.triangles.Length/3+" original upper triangles preserved="+upper);}
if(t.localToWorldMatrix!=targetMatrix||AssetDatabase.AssetPathToGUID(Atlas)!=guid||ShaderUtil.ShaderHasError(material.shader))throw new Exception("Transform/atlas/shader validation failed");var controller=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).FirstOrDefault();bool night=controller&&controller.IsNight;var capture=typeof(CityTaxiStandBuild).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);try{if(controller)controller.Apply(false);capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,7.5f,39)),t.TransformPoint(new Vector3(-.25f,7.6f,10.5f)),"GunShop-Day"});capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,4.4f,25)),t.TransformPoint(new Vector3(-.25f,3.5f,11)),"GunShop-Front"});if(controller)controller.Apply(true);capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,5,32)),t.TransformPoint(new Vector3(-.25f,4.5f,10.5f)),"GunShop-Night"});}finally{if(controller)controller.Apply(night);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/GunShop.txt","SUCCESS: Gun Shop ground floor weapon storefront; original upper building geometry, UVs, normals and original upper material preserved. Same object and three LOD renderers; original transforms/colliders/LOD settings retained. Existing City Hospital Mobile material reused for shop only; original Building2 material retained for unchanged upper/other facades (two existing materials, no new material asset). Shared atlas same4096x2048 GUID/import/compression; hospital/clothing pixels outside reserved gun rectangle differences="+changedOutside+". No added texture asset, detail mesh object, renderer, realtime light, plants, benches, cars or props. Doors about2.5m tall for1.8m player. Summed triangles before="+originalTriangles+" after="+finalTriangles+".\n"+report+"Atlas="+Atlas+"\nBuilt-in image_gen prompt: orthographic WEAPON SHOP frontage, white/amber text, charcoal panels, warm amber LED lines, fictional sporting-weapon wall displays, tactical vests and low glass cases, central double door; all detail baked flat, no background or exterior props.\nSource=FinalEnvironmentRoadReview/GunShop-Facade-Source.png");}static void Polish(){var sc=SceneManager.GetActiveScene();var t=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Single(x=>x.name=="Gun Shop");int total=0;foreach(var f in t.GetComponentsInChildren<MeshFilter>(true)){var m=f.sharedMesh;var p=m.vertices;var uv=new List<Vector4>();m.GetUVs(0,uv);var front=m.GetTriangles(1);var ids=new List<int>();for(int k=0;k<front.Length;k+=3){if(new[]{front[k],front[k+1],front[k+2]}.All(i=>uv[i].x>31&&uv[i].x<33))continue;ids.AddRange(new[]{front[k],front[k+1],front[k+2]});}for(int i=0;i<p.Length;i++)if(uv[i].x>=127){var q=p[i];if(Mathf.Abs(q.y-1.09f)<.001f)q.y=0;else if(Mathf.Abs(q.y-4.0f)<.001f)q.y=3.05f;p[i]=q;}m.vertices=p;m.SetTriangles(ids,1);m.RecalculateBounds();EditorUtility.SetDirty(m);total+=m.triangles.Length/3;}
var capture=typeof(CityTaxiStandBuild).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);var controller=sc.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).FirstOrDefault();bool night=controller&&controller.IsNight;GameObject player=null;try{if(controller)controller.Apply(false);capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,7.5f,39)),t.TransformPoint(new Vector3(-.25f,7.6f,10.5f)),"GunShop-Day"});capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,4.4f,25)),t.TransformPoint(new Vector3(-.25f,3.5f,11)),"GunShop-Front"});player=GameObject.CreatePrimitive(PrimitiveType.Capsule);player.name="Temporary player scale reference1.8m";player.hideFlags=HideFlags.HideAndDontSave;player.transform.SetParent(t,false);player.transform.localPosition=new Vector3(2,.9f,12.4f);player.transform.localScale=new Vector3(.55f,.9f,.55f);capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,3.2f,23)),t.TransformPoint(new Vector3(-.25f,2.1f,11)),"GunShop-PlayerScale"});UnityEngine.Object.DestroyImmediate(player);player=null;if(controller)controller.Apply(true);capture.Invoke(null,new object[]{sc,t.TransformPoint(new Vector3(-.25f,5,32)),t.TransformPoint(new Vector3(-.25f,4.5f,10.5f)),"GunShop-Night"});}finally{if(player)UnityEngine.Object.DestroyImmediate(player);if(controller)controller.Apply(night);}AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);File.AppendAllText("FinalEnvironmentRoadReview/GunShop.txt","\nFINAL: entrance aligned to pavement (localY0), display glazing3.05m and door approximately2.5m, plinth removed,1.8m player-scale preview verified; no temporary player saved. Upper body triangles/UVs/material remain untouched. Final summed LOD triangles="+total+". Shader errors="+ShaderUtil.ShaderHasError(AssetDatabase.LoadAssetAtPath<Material>(MaterialPath).shader));}}
